with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , OTHERSYN as RELATIONSHIP_ELIGIBLE_INDICATOR
        , OTHERRELATION as OTHER_RELATIONSHIP_DESCRIPTION
        , cast(null as varchar) as MEMBER_RELATIONSHIP_CLASS
        , cast(null as varchar) as ELIGIBLE_LIVES_COUNT
        , cast(null as varchar) as AGE_ELIGIBILITY_RESTRICTION
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__REG_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as RELATIONSHIP_ELIGIBLE_INDICATOR
        , cast(null as varchar) as OTHER_RELATIONSHIP_DESCRIPTION
        , MEMBER as MEMBER_RELATIONSHIP_CLASS
        , COUNT as ELIGIBLE_LIVES_COUNT
        , AGE_RESTRICTION as AGE_ELIGIBILITY_RESTRICTION
        , 'BJAZ_GRP_HLT_MEM_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_grp_hlt_mem_dtls') }}
    where (nullif(trim(REG_NO),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then RELATIONSHIP_ELIGIBLE_INDICATOR end) as RELATIONSHIP_ELIGIBLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then OTHER_RELATIONSHIP_DESCRIPTION end) as OTHER_RELATIONSHIP_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_delta3' then MEMBER_RELATIONSHIP_CLASS end) as MEMBER_RELATIONSHIP_CLASS,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ELIGIBLE_LIVES_COUNT end) as ELIGIBLE_LIVES_COUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then AGE_ELIGIBILITY_RESTRICTION end) as AGE_ELIGIBILITY_RESTRICTION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when RELATIONSHIP_ELIGIBLE_INDICATOR is not null or OTHER_RELATIONSHIP_DESCRIPTION is not null or MEMBER_RELATIONSHIP_CLASS is not null or ELIGIBLE_LIVES_COUNT is not null or AGE_ELIGIBILITY_RESTRICTION is not null
                     then md5(upper(coalesce(cast(RELATIONSHIP_ELIGIBLE_INDICATOR as varchar), '') || '|' || coalesce(cast(OTHER_RELATIONSHIP_DESCRIPTION as varchar), '') || '|' || coalesce(cast(MEMBER_RELATIONSHIP_CLASS as varchar), '') || '|' || coalesce(cast(ELIGIBLE_LIVES_COUNT as varchar), '') || '|' || coalesce(cast(AGE_ELIGIBILITY_RESTRICTION as varchar), '')))
                end as SAT_POLICY_GROUP_RELATION_ELIGIBILITY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_GROUP_RELATION_ELIGIBILITY_HASHDIFF is not null
